import json
import sqlite3

STEPS = ["install", "tutorial_complete", "first_match", "purchase"]

con = sqlite3.connect("analytics.db")

# Reporting rules: test accounts and events from unknown players do not count.
valid = {u: p for u, p in con.execute(
    "SELECT user_id, platform FROM users WHERE is_test = 0")}

events = {}  # user_id -> {step: [ts,...]}
for u, name, ts in con.execute("SELECT user_id, name, ts FROM events"):
    if u in valid and name in STEPS:
        events.setdefault(u, {}).setdefault(name, []).append(ts)

funnel = {}  # platform -> {step: count}
for u, platform in valid.items():
    counts = funnel.setdefault(platform, dict.fromkeys(STEPS, 0))
    prev_ts = None  # no time limit; first valid occurrence at or after previous step
    reached = []
    for step in STEPS:
        cands = events.get(u, {}).get(step, [])
        if prev_ts is not None:
            cands = [t for t in cands if t >= prev_ts]
        if not cands:
            break
        prev_ts = min(cands)
        reached.append(step)
    for step in reached:
        counts[step] += 1

biggest_drop = {}
for platform, counts in sorted(funnel.items()):
    best_step, best_conv = None, None
    for i in range(1, len(STEPS)):
        prev, cur = counts[STEPS[i - 1]], counts[STEPS[i]]
        if prev == 0:
            continue
        conv = cur / prev
        if best_conv is None or conv < best_conv:
            best_step, best_conv = STEPS[i], conv
    biggest_drop[platform] = {
        "step": best_step,
        "conversion": round(best_conv, 4) if best_conv is not None else None,
    }

result = {"funnel": {p: funnel[p] for p in sorted(funnel)},
          "biggest_drop": {p: biggest_drop[p] for p in sorted(biggest_drop)}}
with open("result.json", "w", encoding="utf-8") as f:
    json.dump(result, f, indent=2)
print(json.dumps(result, indent=2))

# Diagnostics: excluded data sanity
all_users = con.execute("SELECT COUNT(*) FROM users").fetchone()[0]
tests = all_users - len(valid)
unknown = con.execute(
    "SELECT COUNT(*) FROM events e LEFT JOIN users u ON e.user_id=u.user_id "
    "WHERE u.user_id IS NULL").fetchone()[0]
test_events = con.execute(
    "SELECT COUNT(*) FROM events e JOIN users u ON e.user_id=u.user_id "
    "WHERE u.is_test=1").fetchone()[0]
print(f"users={all_users} test_users={tests} unknown-player events={unknown} "
      f"test-player events={test_events}")
print("event names:", [r[0] for r in con.execute("SELECT DISTINCT name FROM events")])


