import sqlite3

con = sqlite3.connect("analytics.db")
for name, sql in con.execute("SELECT name, sql FROM sqlite_master WHERE type='table'"):
    print(sql, "\n")
    n = con.execute(f"SELECT COUNT(*) FROM {name}").fetchone()[0]
    print(name, "rows:", n)
    cols = [d[1] for d in con.execute(f"PRAGMA table_info({name})")]
    print(cols)
    for r in con.execute(f"SELECT * FROM {name} LIMIT 8"):
        print(r)
    print("---")


